import { act, renderHook } from '@testing-library/react';
import { afterEach, expect, it, vi } from 'vitest';
import { useResource } from './Solution';

/**
 * 沙箱不跑 tsc，判分只看运行时行为；但契约里的判别联合仍要写对：
 * status 是唯一判别式，promise 在 idle 时为 null。
 */
interface Call {
  key: string;
  signal: AbortSignal;
  resolve: (v: { name: string }) => void;
  reject: (e: unknown) => void;
}

interface State {
  status: string;
  data?: { name: string };
  error?: unknown;
  promise: unknown;
}

const stateOf = (s: unknown): State => s as State;

/** 受控 fetch 替身：把"何时返回"的决定权交给用例，所以不需要假计时器。 */
function makeFetch() {
  const calls: Call[] = [];
  const impl = (key: string, signal: AbortSignal) => {
    let resolve: (v: { name: string }) => void = () => undefined;
    let reject: (e: unknown) => void = () => undefined;
    const p = new Promise((res, rej) => {
      resolve = res;
      reject = rej;
    });
    // 被丢弃的响应不允许变成 unhandled rejection 干扰判题
    p.catch(() => undefined);
    calls.push({ key, signal, resolve: (v) => resolve(v), reject: (e) => reject(e) });
    return p;
  };
  return { calls, impl };
}

function abortError() {
  const e = new Error('The user aborted a request.');
  e.name = 'AbortError';
  return e;
}

afterEach(() => {
  vi.restoreAllMocks();
});

it('单次请求不重复发起并进入 loading', async () => {
  const f = makeFetch();
  const { result, rerender } = renderHook(({ k }: { k: string | null }) => useResource(k, f.impl), {
    initialProps: { k: 'u/1' as string | null },
  });
  expect(stateOf(result.current).status).toBe('loading');
  expect(f.calls.length).toBe(1);
  const first = stateOf(result.current).promise;
  rerender({ k: 'u/1' });
  rerender({ k: 'u/1' });
  expect(f.calls.length).toBe(1);
  expect(stateOf(result.current).promise).toBe(first);
  await act(async () => {
    f.calls[0].resolve({ name: 'Ada' });
  });
  expect(stateOf(result.current).status).toBe('ready');
  expect(stateOf(result.current).data?.name).toBe('Ada');
});

it('空 key 不发请求保持 idle', () => {
  const f = makeFetch();
  const { result } = renderHook(() => useResource('', f.impl));
  expect(f.calls.length).toBe(0);
  expect(stateOf(result.current).status).toBe('idle');
  expect(stateOf(result.current).promise).toBe(null);
});

it('切换 key 时取消上一个请求', () => {
  const f = makeFetch();
  const { result, rerender } = renderHook(({ k }: { k: string | null }) => useResource(k, f.impl), {
    initialProps: { k: 'u/1' as string | null },
  });
  rerender({ k: 'u/2' });
  expect(f.calls.length).toBe(2);
  expect(f.calls[0].signal.aborted).toBe(true);
  expect(f.calls[1].signal.aborted).toBe(false);
  expect(stateOf(result.current).status).toBe('loading');
});

it('并发乱序返回时旧响应晚到不污染新数据', async () => {
  const f = makeFetch();
  const { result, rerender } = renderHook(({ k }: { k: string | null }) => useResource(k, f.impl), {
    initialProps: { k: 'u/1' as string | null },
  });
  rerender({ k: 'u/2' });
  await act(async () => {
    f.calls[1].resolve({ name: 'Grace' });
  });
  expect(stateOf(result.current).status).toBe('ready');
  await act(async () => {
    f.calls[0].resolve({ name: 'Ada' });
  });
  expect(stateOf(result.current).status).toBe('ready');
  expect(stateOf(result.current).data?.name).toBe('Grace');
});

it('卸载后取消请求且晚到响应不再写状态', async () => {
  const noise: string[] = [];
  vi.spyOn(console, 'error').mockImplementation((...args: unknown[]) => {
    noise.push(args.map(String).join(' '));
  });
  const f = makeFetch();
  const { unmount } = renderHook(() => useResource('u/1', f.impl));
  unmount();
  expect(f.calls[0].signal.aborted).toBe(true);
  await act(async () => {
    f.calls[0].resolve({ name: 'Ada' });
  });
  expect(noise).toEqual([]);
});

it('AbortError 取消回落 idle 不进失败态', async () => {
  const f = makeFetch();
  const { result } = renderHook(() => useResource('u/1', f.impl));
  await act(async () => {
    f.calls[0].reject(abortError());
  });
  expect(stateOf(result.current).status).toBe('idle');
  expect(stateOf(result.current).error).toBeUndefined();
});

it('真实失败进入 error 并原样保留 unknown 原因', async () => {
  const f = makeFetch();
  const { result } = renderHook(() => useResource('u/1', f.impl));
  await act(async () => {
    f.calls[0].reject('boom');
  });
  expect(stateOf(result.current).status).toBe('error');
  expect(stateOf(result.current).error).toBe('boom');
});

