import { useEffect, useRef, useState } from 'react';

export type ResourceState<T> =
  | { status: 'idle'; promise: null }
  | { status: 'loading'; promise: Promise<T> }
  | { status: 'ready'; promise: Promise<T>; data: T }
  | { status: 'error'; promise: Promise<T>; error: unknown };

/** 取消不是失败：DOMException/Error 的 name 为 AbortError 时走独立分支。 */
function isCancellation(error: unknown): boolean {
  if (typeof error !== 'object' || error === null) return false;
  return (error as { name?: unknown }).name === 'AbortError';
}

export function useResource<T>(
  key: string | null,
  fetchImpl: (key: string, signal: AbortSignal) => Promise<T>,
): ResourceState<T> {
  const [state, setState] = useState<ResourceState<T>>({ status: 'idle', promise: null });
  /** 代数令牌：只有最新那代能写状态，晚到的旧响应直接丢弃。 */
  const generation = useRef(0);
  const implRef = useRef(fetchImpl);
  useEffect(() => {
    implRef.current = fetchImpl;
  });

  useEffect(() => {
    if (!key) {
      generation.current += 1;
      setState({ status: 'idle', promise: null });
      return;
    }
    const controller = new AbortController();
    const token = (generation.current += 1);
    const promise = implRef.current(key, controller.signal);
    if (generation.current === token) setState({ status: 'loading', promise });
    promise.then(
      (data) => {
        if (generation.current !== token) return;
        setState({ status: 'ready', promise, data });
      },
      (error: unknown) => {
        if (generation.current !== token) return;
        if (isCancellation(error) || controller.signal.aborted) {
          setState({ status: 'idle', promise: null });
          return;
        }
        setState({ status: 'error', promise, error });
      },
    );
    return () => {
      generation.current += 1;
      controller.abort();
    };
  }, [key]);

  return state;
}

