import { useEffect, useState } from 'react';

export function useResource(
  key: string | null,
  fetchImpl: (key: string, signal: AbortSignal) => Promise<unknown>,
) {
  const [state, setState] = useState<unknown>({ status: 'idle', promise: null });
  useEffect(() => {
    if (!key) {
      setState({ status: 'idle', promise: null });
      return;
    }
    const controller = new AbortController();
    const promise = fetchImpl(key, controller.signal);
    setState({ status: 'loading', promise });
    promise.then(
      (data) => setState({ status: 'ready', promise, data }),
      (error: unknown) => setState({ status: 'error', promise, error }),
    );
  }, [key, fetchImpl]);
  return state;
}
